  ('Figuras Negras', 'Oro', 0, 0, 'Leyendas Primer Bloque 4.0', '', 1000, 'https://drive.google.com/thumbnail?id=1EaLS5YVoghymEsaIyIavMTRvaTmQnW1y&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
