  ('Archimago', 'Aliado', 2, 3, 'Leyendas Primer Bloque 4.0', 'Cuando entra en juego, puedes jugar un Talismán de coste 3 o menos de tu Cementerio sin pagar su coste. Luego, Destierra ese Talismán.', 2500, 'https://drive.google.com/thumbnail?id=1in-W6MJBLTl8FW84M0-QNQhzFtd9v2lE&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Faerie')),
  ('Mordred', 'Aliado', 3, 3, 'Leyendas Primer Bloque 4.0', 'Puede atacar cuando entra en juego.  Cuando es declarado atacante, debe ser bloqueado por un Aliado oponente a tu elección.', 2500, 'https://drive.google.com/thumbnail?id=1h16F3HxFWhF92vHnbi2zd6KmacngSwH_&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Faerie')),
