  ('Trono Dorado', 'Oro', 0, 0, 'Leyendas Primer Bloque 4.0', '', 1000, 'https://drive.google.com/thumbnail?id=1PHkO5K_MMG-NakHe9kIprXhypT_G57HK&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
