  ('Forma de Niebla', 'Talismán', 0, 0, 'Leyendas Primer Bloque 4.0', '', 1000, 'https://drive.google.com/thumbnail?id=1rT2KtYToHpqnKxxdVzvE3r6DoSn_I__V&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Danza Sidhe', 'Talismán', 0, 1, 'Leyendas Primer Bloque 4.0', 'Roba 2 cartas. Luego, descarta 2 cartas. Si esta carta está en tu Cementerio, y controlas Aliados Sidhe, puedes ponerla al fondo de tu Mazo Castillo.', 1500, 'https://drive.google.com/thumbnail?id=1dnQaSOD6bIJNJpzZamz8JrYl_DltvXZ6&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Cegar el Mal', 'Talismán', 0, 1, 'Leyendas Primer Bloque 4.0', 'Elige entre destruir un Aliado en juego que no pueda ser declarado atacante o que un Aliado oponente no pueda ser declarado bloqueador este turno.', 1500, 'https://drive.google.com/thumbnail?id=1rmFVH6TVbMHhLnbMAuTAolc_xfJkqOpr&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Cambiar de Forma', 'Talismán', 0, 4, 'Leyendas Primer Bloque 4.0', 'Tus Aliados ganan 2 a la fuerza hasta la Fase Final. Roba 2 cartas.', 3000, 'https://drive.google.com/thumbnail?id=1YeeJy2ejcvUR-Gee6AZZiKQytm0nGr95&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Escudo Sidhe', 'Arma', 0, 2, 'Leyendas Primer Bloque 4.0', 'Una vez por turno, descarta una carta de tu mano para que un Aliado Sidhe gane tanta fuerza como coste tenga esa carta.', 2000, 'https://drive.google.com/thumbnail?id=1mKySez020PWITfCoILlhpDBL1-h-iwET&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Broche de Tara', 'Oro', 0, 0, 'Leyendas Primer Bloque 4.0', 'Sólo puedes activar un Broche de Tara por turno. Cuando entra en juego, nombra una raza. Cada vez que uses este Oro para pagar el coste de un Aliado de la raza nombrada, tu oponente bota 1 carta.', 1000, 'https://drive.google.com/thumbnail?id=1qmnjvnfg_Suf2F6O1m-XhzHyzvRVHAVE&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Pilar Botero', 'Oro', 0, 0, 'Leyendas Primer Bloque 4.0', 'En tu Fase de Vigilia, una vez por turno, puedes pagar este Oro y otro Oro que controles para que un Aliado sea Imbloqueable hasta la Fase Final.', 1000, 'https://drive.google.com/thumbnail?id=1XyjJlLtpDXtWuVA6OnmIX-dHrMiYrmnM&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Salmon del Saber', 'Oro', 0, 0, 'Leyendas Primer Bloque 4.0', '', 1000, 'https://drive.google.com/thumbnail?id=1Om-5AKusLHmQzxCpoAVlGDXsrSr_Pcd8&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Shezmu', 'Aliado', 3, 3, 'Leyendas Primer Bloque 4.0', 'Puede atacar cuando entra en juego. Tus Aliados que sean bloqueados ganan 2 a la fuerza hasta la Fase Final. Cuando es destruido, puedes buscar un Aliado de raza Eterno de coste 2 o menos en tu Mazo Castillo y ponerlo en tu Mano.', 2500, 'https://drive.google.com/thumbnail?id=10_ic6e1X3_ypykQIi8qBjOznA8DrHtuA&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Eterno')),
  ('Aker', 'Aliado', 3, 3, 'Leyendas Primer Bloque 4.0', 'Única. Una vez por turno, puedes copiar la habilidad de una carta en juego que no sea Oro hasta la Fase Final.', 2500, 'https://drive.google.com/thumbnail?id=1iGPCt-nvv6yc20On91AD0PEhLv2haWxH&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Eterno')),
  ('Merodeador de las Arenas', 'Aliado', 2, 2, 'Leyendas Primer Bloque 4.0', 'Puede atacar cuando entra en juego. Hasta dos veces por turno, puedes desterrar una carta de tu Cementerio para que este u otro Aliado que controles gane 1 a la fuerza hasta la fase final.', 2000, 'https://drive.google.com/thumbnail?id=1NHX3VD3AZWUPKIO24J5L6k1kgzcH-wlc&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Faraón')),
  ('Van Helsing', 'Aliado', 2, 3, 'Leyendas Primer Bloque 4.0', '', 2500, 'https://drive.google.com/thumbnail?id=1VHBNsJAXe8THyJs-nkqdPnQUOcOCOo8K&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Caballero')),
  ('Alejandro Ii', 'Aliado', 3, 3, 'Leyendas Primer Bloque 4.0', 'No puede ser anulado. Indestructible. Puede atacar cuando entra en juego.', 2500, 'https://drive.google.com/thumbnail?id=1lby40wW4VQx0bpqhQ0E2jggWuqiaGhXl&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Faraón')),
  ('Senenmut', 'Aliado', 2, 2, 'Leyendas Primer Bloque 4.0', 'Cuando entra o salga del juego, puedes barajar tantas cartas de tu Cementerio como fuerza de este Aliado.', 2000, 'https://drive.google.com/thumbnail?id=1LQKAczZnhCBs6LX_n-MEB17kKBNDZke1&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sacerdote')),
  ('Werin el Poseido', 'Aliado', 3, 2, 'Leyendas Primer Bloque 4.0', 'No puede ser afectado por habilidades de Aliados oponentes. Cuando salga del juego, puedes buscar un Talismán en tu Mazo Castillo y ponerlo en tu Mano.', 2000, 'https://drive.google.com/thumbnail?id=17P7znXUp3gCxynkM7LzUloU4vrCNG5bY&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sacerdote')),
  ('Sheut', 'Talismán', 0, 1, 'Leyendas Primer Bloque 4.0', 'Anula una carta jugada sin pagar su coste. Luego, destierra la carta anulada.', 1500, 'https://drive.google.com/thumbnail?id=1X-4fhEt8tkwq66S8RVQ2YXa5f-9CRM-Q&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Purificar Esencias', 'Talismán', 0, 3, 'Leyendas Primer Bloque 4.0', 'Sólo puedes jugar este Talismán en la Fase de Asignación de daño. Reduce todo el daño a 0. Luego, puedes desterrar una carta del Cementerio oponente por cada Aliado que fue declarado atacante este turno.', 2500, 'https://drive.google.com/thumbnail?id=1nvEwp-Xu6-gGH6DT2CsgqHznZm3bcWMC&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Hacha Solar', 'Arma', 0, 3, 'Leyendas Primer Bloque 4.0', 'Cuando el portador sea declarado atacante debe ser bloqueado este turno. Una vez por turno, puedes desterrar un Oro de tu Cementerio para barajar dos cartas de tu Cementerio en tu Mazo Castillo.', 2500, 'https://drive.google.com/thumbnail?id=1iZF1qCIC2_eELqzaSBvK1701J7UW4uFw&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Ave Bennu', 'Oro', 0, 0, 'Leyendas Primer Bloque 4.0', 'En tu Fase de Vigilia, puedes pagar 3 Oros para convertir a este Oro en un Aliado de coste y fuerza 3 hasta la Fase Final. Si hace daño al Mazo Castillo oponente, puedes desterrarlo para buscar un Oro en tu Mazo Castillo y ponerlo en tu zona de Oro Pagado.', 1000, 'https://drive.google.com/thumbnail?id=1y8lwYgGy9L-XHJhtXufcsZzVVvXXkigN&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Garras de Bronce', 'Arma', 0, 3, 'Leyendas Primer Bloque 4.0', 'El portador gana 3 a la fuerza. Cuando el portador sea declarado atacante o bloqueador, es Indestructible hasta la Fase Final.', 2500, 'https://drive.google.com/thumbnail?id=1a15IUAPyDZeXSaoUBpXLfqd2FY7tU9iL&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
  ('Castillo de Drácula', 'Tótem', 0, 3, 'Leyendas Primer Bloque 4.0', 'Cuando entra en juego, destierra una carta en juego que no sea Oro. Luego, busca en tu Mazo Castillo o Cementerio un Aliado Drácula de coste igual o menor a la carta desterrada y ponlo en tu Mano. Puedes destruir este Tótem para que tus Aliados Drácula ganen 1 a la fuerza hasta la Fase Final.', 2500, 'https://drive.google.com/thumbnail?id=1iAaCJlWTR7NetbHac4Z3xNwdXETRBq7a&sz=w400', (SELECT categoria_id FROM demo_categorias WHERE nombre = 'Sin Raza')),
